const w = $('Qualified to Buy Webhook').first().json;
const raw = w.body ?? w;
const dealId = String(raw.id || '').trim();
const props = raw.properties || {};
const config = $('Get Config').first().json;
if (!dealId) throw new Error('Missing deal id on webhook body');
return [{ json: { dealId, props, config } }];

const deal = $('Fetch Deal From HubSpot').first().json;
const contact = $json;
const ctx = $('Prep Context').first().json;
const config = ctx.config;
const props = deal.properties || ctx.props || {};
const contactProps = contact.properties || {};
const assoc = deal.associations?.contacts?.results || [];
const hubspotContactId = assoc[0]?.id ? String(assoc[0].id) : '';
const email = (props.contact_email || contactProps.email || '').trim().toLowerCase();
const first = (props.contact_firstname || contactProps.firstname || '').trim();
const last = (props.contact_lastname || contactProps.lastname || '').trim();
const phone = (props.contact_phone || contactProps.phone || '').trim();
const companyName = (props.dealname || props.company || '').trim() || 'Client';
const dealId = ctx.dealId;
if (!hubspotContactId) {
  throw new Error('Deal has no associated contact. Associate a primary contact in HubSpot before this stage.');
}
if (!email) {
  throw new Error('Missing contact email. Populate deal contact_email or associated contact email before this stage.');
}
const secrets = config.secrets || {};
const webhookSecret = String(secrets.webhookSecret || '').trim();
const clerkSecret = String(secrets.clerkSecretKey || '').trim();
const portalCfg = String(config.owner?.portalN8nWebhookUrl || '').trim();
const portalTbl = String(secrets.portalWebhookUrl || '').trim();
const signUpCfg = String(config.owner?.portalSignUpUrl || '').trim();
const signUpTbl = String(secrets.portalSignUpRedirectUrl || '').trim();
const tier = (props.tier || '').toLowerCase();
const plan = tier === 'growth' ? 'growth' : tier === 'custom' ? 'custom' : 'starter';
const slugBase = companyName.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '') || 'client';
const project_slug = (slugBase + '-' + dealId).slice(0, 48);
const portalBase = (portalCfg || portalTbl || 'https://portal.intrawebtech.com').trim();
let portalUrl = '';
if (portalBase) {
  portalUrl = portalBase.includes('/api/webhook/n8n')
    ? portalBase
    : portalBase.replace(/\/$/, '') + '/api/webhook/n8n';
}
const signUp = (signUpCfg || signUpTbl || '').trim();
if (!portalUrl) {
  throw new Error('Missing portal webhook URL. Configure CONFIG owner.portalN8nWebhookUrl or secrets.portalWebhookUrl.');
}
if (!webhookSecret) {
  throw new Error('Missing webhookSecret in CONFIG secrets table.');
}
if (!clerkSecret) {
  throw new Error('Missing clerkSecretKey in CONFIG secrets table.');
}
const today = new Date().toISOString().slice(0, 10);
const provisionBody = {
  action: 'provision_client',
  project_slug,
  data: {
    name: (first + ' ' + last).trim() || companyName,
    email,
    phone: phone || undefined,
    hubspot_contact_id: hubspotContactId,
    hubspot_deal_id: dealId,
    plan,
    start_date: today,
    engagement_phase: 'qualified',
    seed_template_invoices: false,
  },
};
return [{
  json: {
    portalUrl,
    signUp,
    webhookSecret,
    clerkSecret,
    provisionBody,
    inviteEmail: email,
  },
}];

return (async () => {
  const portal = $('POST Portal provision_client').first().json;
  const bp = $('Build provision payload').first().json;
  const deal = $('Fetch Deal From HubSpot').first().json;
  const skipInvite = !!portal.idempotent;
  const out = { ...bp, skipInvite, portal };
  if (!skipInvite) {
    const props = deal.properties || {};
    const raw = props.amount;
    const n = parseFloat(String(raw ?? '0').replace(/,/g, ''));
    const cents = Math.round(n * 100);
    const did = bp.provisionBody?.data?.hubspot_deal_id;
    if (cents >= 50 && did) {
      const addInvoice = {
        action: 'add_invoice',
        hubspot_deal_id: String(did),
        data: {
          invoice_number: 'INV-HS-' + String(did).replace(/\D/g, '').slice(0, 32),
          description: 'Per HubSpot deal amount (includes any discounts; add more add_invoice calls for deposits or balance).',
          amount_cents: cents,
          status: 'pending',
        },
      };
      try {
        const res = await fetch(bp.portalUrl, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json', 'x-intrawebtech-secret': bp.webhookSecret },
          body: JSON.stringify(addInvoice),
        });
        const text = await res.text();
        let result = null;
        try { result = JSON.parse(text); } catch (err) { result = { raw: text }; }
        out.hubspot_amount_invoice = { ok: res.ok, status: res.status, result };
      } catch (e) {
        out.hubspot_amount_invoice = { ok: false, error: e && e.message ? e.message : String(e) };
      }
    }
  }
  return [{ json: out }];
})();

const bp = $('After portal response').first().json;
let clerk = 'skipped_user_exists';
if (bp.skipInvite) clerk = 'skipped_portal_idempotent';
return [{ json: { ok: true, clerk, portal: bp.portal, inviteEmail: bp.inviteEmail } }];

const bp = $('After portal response').first().json;
const inv = $json;
return [{ json: { ok: true, clerk: 'invited', invitation_id: inv.id || null, portal: bp.portal, inviteEmail: bp.inviteEmail } }];

